function sat_add_signed_6bit(val, step):
  res = val + step
  if res > 31:
    return 31
  if res < -32:
    return -32
  return res

function update_sR(PC, outcome, recorded_valid_regs_at_pred, recorded_selected_regs):
  for bank = 0 to 7:
    available_regs = [r for r in recorded_valid_regs_at_pred if (r % 8 == bank)]
    if len(available_regs) == 0:
      continue

    // If multiple registers were available, randomly select one to update
    r_update = available_regs[random_choice(len(available_regs))]
    digest = recorded_digest[r_update]

    // Update weight tables WT0, WT1, WT2 using perceptron rule
    h0 = hash_wt0(PC, digest); h1 = hash_wt1(PC, digest); h2 = hash_wt2(PC, digest)
    step = (outcome == TAKEN) ? +1 : -1
    prediction_weight_tables[bank].WT0[h0] = sat_add_signed_6bit(prediction_weight_tables[bank].WT0[h0], step)
    prediction_weight_tables[bank].WT1[h1] = sat_add_signed_6bit(prediction_weight_tables[bank].WT1[h1], step)
    prediction_weight_tables[bank].WT2[h2] = sat_add_signed_6bit(prediction_weight_tables[bank].WT2[h2], step)

    // Update usefulness tables UT0, UT1, UT2
    // Usefulness increments if WT direction agreed with outcome, else decrements
    wt_sum = prediction_weight_tables[bank].WT0[h0] + prediction_weight_tables[bank].WT1[h1] + prediction_weight_tables[bank].WT2[h2]
    pred_agreed = ((wt_sum >= 0) == (outcome == TAKEN))
    u_step = pred_agreed ? +1 : -1
    idx0 = hash_ut0(PC); idx1 = hash_ut1(PC); idx2 = hash_ut2(PC)
    usefulness_weight_tables[bank].UT0[idx0][r_update] = sat_add_signed_6bit(usefulness_weight_tables[bank].UT0[idx0][r_update], u_step)
    usefulness_weight_tables[bank].UT1[idx1][r_update] = sat_add_signed_6bit(usefulness_weight_tables[bank].UT1[idx1][r_update], u_step)
    usefulness_weight_tables[bank].UT2[idx2][r_update] = sat_add_signed_6bit(usefulness_weight_tables[bank].UT2[idx2][r_update], u_step)
